// Secure and robust Express.js application with input validation and error handling
// Focus: Security best practices for error handling and input validation

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const { query, validationResult } = require('express-validator');
const rateLimit = require('express-rate-limit');

const app = express();

// Security Middleware Setup
app.use(helmet()); // Secure HTTP headers
app.use(cors({ origin: process.env.CORS_ORIGIN || 'http://localhost:3000' }));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
});
app.use(limiter);

// Input Parser with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Sanitize helper (basic XSS protection)
function sanitize(text) {
  if (!text || typeof text !== 'string') return '';
  return text.replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Health endpoint with no external dependencies
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation and sanitization
app.get('/users',
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('q').optional().isString().trim().isLength({ max: 50 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array().map(e => e.msg) });
    }

    // Sample user data (in production, this would use sanitized DB queries)
    const users = [
      { id: 1, name: sanitize('Alice'), email: sanitize('alice@example.com') },
      { id: 2, name: sanitize('Bob'), email: sanitize('bob@example.com') },
      { id: 3, name: sanitize('Carol'), email: sanitize('carol@example.com') },
    ];

    // Dynamic filtering based on input, safely cast
    let result = users;
    if (req.query.id) {
      result = result.filter(u => u.id === req.query.id);
    }
    if (req.query.q) {
      const term = req.query.q.toLowerCase();
      result = result.filter(u => 
        u.name.toLowerCase().includes(term) || 
        u.email.toLowerCase().includes(term)
      );
    }

    res.json(result);
  }
);

// 404 - Resource not found handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Error handling middleware - catches unhandled errors and prevents stack trace leak
app.use((err, req, res, next) => {
  console.error(`Error: ${err.message}`, { path: req.path, stack: process.env.NODE_ENV === 'development' ? err.stack : undefined });
  res.status(500).json({ error: 'Internal Server Error' });
});

// Load port from environment with fallback
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Listening on port ${PORT}`);
});

module.exports = app;

